// Classes du Grand Sec (post-apocalyptique, vallée du Rhône asséchée, an 40 du Sec) : dix classes, deux sous-classes chacune.
// Caractéristiques du genre : 0 Force, 1 Agilité, 2 Endurance, 3 Savoir, 4 Instinct, 5 Présence.
// Aucun sort : des métiers, des bêtes, des machines et un prix en eau pour les grands efforts.
// Ce prix se paie en godets (section « Ce que coûte l'effort » de sec-regles.ts) : au plus 4 godets de pouvoirs par jour, 8 à partir du niveau 11.
// Les niveaux élevés donnent des relations, des talents et des réserves, jamais des surhommes.
// Les textes sont lus par les joueurs : aucun secret du canon (shared/canon/post-apo.ts) ici.
import type { ActionType, CharacterClass, Power, Recharge, Subclass } from "./rules";

const P = (level: number, name: string, action: ActionType, recharge: Recharge, effect: string, extra: Partial<Power> = {}): Power => ({ level, name, action, recharge, effect, ...extra });
const S = (id: string, name: string, pitch: string, description: string, powers: Power[]): Subclass => ({ id, name, pitch, description, powers });

/** Un grand effort se paie en eau : N godets versés de la gourde. */
const EAU = (n: number) => ` Prix : ${n} godet${n > 1 ? "s" : ""}.`;

/** Le passif commun aux classes dont certains pouvoirs coûtent de l'eau. */
const PRIX_COMMUN =
  "Un pouvoir marqué « Prix : N godets » se paie en eau : tu retires N godets de ta gourde : c'est l'eau que l'effort te fait perdre en sueur. Elle ne compte pas dans ta ration. Si ta gourde ne suffit pas, tu peux utiliser le pouvoir quand même, et tu prends un niveau d'épuisement par godet manquant. Tu ne peux pas payer plus de 4 godets de pouvoirs par jour (8 à partir du niveau 11) : passé ce compte, le corps ne suit plus et le pouvoir ne marche pas. Un seul pouvoir à prix par round, réaction comprise. Les autres pouvoirs sont des savoir-faire : ils ne coûtent rien.";

const PRIX_PENITENT =
  PRIX_COMMUN +
  " Toi seul peux payer en jeûne : au lieu de retirer des godets, tu renonces à autant de godets de ta ration du jour (ils comptent comme de l'eau non bue ; la règle de la soif s'applique le soir, avec l'avantage à ta sauvegarde).";

/** DD des pouvoirs qui demandent une sauvegarde. */
const DD = " DD de la sauvegarde : 8 + ta maîtrise + ton modificateur de caractéristique principale.";

